 async function startBatch(){if(busy)return;const clash=selected.find(s=>repeated(songStyles(s)).length);if(clash){notice(`《${clash.name}》的各版本请选择不同风格。`);return}const crowded=selected.find(s=>songSuite(s)&&!songAll(s)&&songCount(s)+suiteParts.length>20);if(crowded){notice(`《${crowded.name}》加上管弦组曲的 ${suiteParts.length} 个版本后超过 20 个，请减少版本数或关闭组曲。`);return}if(suiteCount&&repeated(suite.styles).length){notice('管弦组曲的三个部分请选择不同风格。');return}if(selected.length>100){notice('每批最多 100 首；队列可累计 2000 首。');return}if(voiceMissing){notice('本机还没有安装换声引擎（Seed-VC），请先安装或关闭“换成原唱音色”。');return}setBusy(true);try{await saves.current;requestKey.current ||= crypto.randomUUID();await api('/api/batch',{request_id:requestKey.current,items:selected.map(s=>({track_id:s.id,engine:'yue2',instrumental:s.instrumental,mode:s.instrumental?'remix':s.mode||mode,format,profile,gender:s.gender||gender,tone:s.tone||tone,lyrics:s.lyrics,change_strength:s.change_strength??strength,melody_mode:s.melody_mode||melodyMode,instructions:s.instructions?.trim()||instructions,adjust:s.adjust||adjust,voice_swap:s.voice_swap||voiceSwap,speed_variants:s.speed_variants??speedVariants,smart_defaults:smartDefaults,explicit:[s.mode&&'mode',s.melody_mode&&'melody_mode',s.adjust&&'adjust'].filter(Boolean),suite:songSuite(s)?{styles:suite.styles}:null,all_styles:songAll(s),...(songAll(s)?{}:{variants:songStyles(s).map((v,i)=>({style:v,variant_instructions:versionNotes[i]}))})}))});requestKey.current=null;setDialog(null);setView('queue');await refresh();window.scrollTo(0,0);notice(`${totalVersions} 个版本已加入本机队列。`+(speedVersions>0?`版本完成后再自动生成 ${speedVersions} 个变速版本。`:'')+(suiteCount>0?`管弦版本完成后自动衔接 ${suiteCount} 首组曲。`:'')+(speedVersions+suiteCount>0?`共 ${totalVersions+speedVersions+suiteCount} 个作品。`:''))}catch(e){notice(e.message)}finally{setBusy(false)}}
