 async function remove(s){try{await persist('/api/tracks/'+s.id,{hidden:true});if(playing===s.id){audio.current?.pause();setPlaying(null)}setSongs(prev=>prev.filter(x=>x.id!==s.id));notice('已从列表移除，原音频与作品仍保存在本机。')}catch(e){notice(e.message)}}
