 function outputCard(j){const derived=!!j.kind,parent=derived&&jobs.find(x=>x.id===j.parent_id),picked=mixPick?.includes(j.id);return <article className={'version-card'+(derived?' derived':'')+(picked?' picked':'')} key={j.id}>{mixPick&&<label className="mix-pick"><input type="checkbox" aria-label={'加入 DJ 串烧 '+j.output_name} checked={!!picked} onChange={e=>{const on=e.target.checked;setMixPick(prev=>on?[...prev,j.id]:prev.filter(id=>id!==j.id))}}/>加入串烧{picked?' · 第 '+(mixPick.indexOf(j.id)+1)+' 首':''}</label>}<div className="version-heading"><span className="version-badge">{kindBadge(j)}</span><span>{derived?kindNote(j):profiles[j.config?.profile]||'历史设置'}</span></div><h3>{j.output_name}</h3><p>{derived?kindText(j):j.config?.instrumental?'纯音乐':j.mode==='preserve'?'原始人声':`${genders[j.config?.gender]||'自动'} · ${tones[j.config?.tone]||'自然'}`} · {fmt(j.checks?.result?.seconds||j.duration)}</p><p>{j.config?.app_version?'v'+j.config.app_version:'历史版本 · 未记录'}{derived?(j.kind==='mix'?' · 来自 '+(j.parent_ids?.length||0)+' 首作品':j.kind==='suite'?' · 来自 3 个管弦版本':' · 来自 '+(parent?.output_name||'原作品'))+' · 未重新生成':j.config?.change_strength!=null?' · 力度 '+j.config.change_strength+'% · '+melodyModes[j.config.melody_mode]:''}</p>{!derived&&j.adjust&&<p>生成前变调变速 · {adjustText(j.adjust)}</p>}{!derived&&j.voice&&<p className="voice-line">{j.voice_info?.skipped?'未检测到生成人声 · 保留原声':'换成原唱音色 · Seed-VC'+(j.voice_info?' · '+shiftText(j.voice_info.octave_shift):'')}</p>}{!derived&&j.kid&&<p className="voice-line">{kidText(j.kid_info)}</p>}{!derived&&Object.keys(j.smart_defaults||{}).length>0&&<p>智能默认 · {smartText(j.smart_defaults)}</p>}<p className="processing-time">{j.timing_source==='legacy_wall_time'?'历史处理用时（估算）':'实际处理用时'} <b>{elapsed(j.processing_seconds)}</b></p><audio onPlay={e=>{document.querySelectorAll('audio').forEach(a=>{if(a!==e.currentTarget)a.pause()});audio.current?.pause();setPlaying(null)}} aria-label={`${j.title} ${j.variant||''} 试听`} controls preload="none" src={j.urls.result}/><div className="version-actions"><button className={'secondary '+(j.favorite?'favorited':'')} aria-pressed={!!j.favorite} onClick={()=>jobAction(j.id,'favorite')}>{j.favorite?'★ 已收藏':'☆ 收藏'}</button>{(j.config?.format!=='mp3'||!j.urls.mp3)&&<a className="secondary" href={j.urls.result} download={j.output_name+'.wav'}>WAV</a>}{j.urls.mp3&&j.config?.format!=='wav'&&<a className="secondary" href={j.urls.mp3} download={j.output_name+'.mp3'}>MP3</a>}{!j.hidden&&<button className="secondary" onClick={()=>openAdjust(j)}>变调 / 变速</button>}{!j.hidden&&<button className="secondary" onClick={()=>openDj(j)}>DJ 效果</button>}<button className="text-button" onClick={()=>{setDetail(j);setDialog('detail')}}>参数与歌词</button>{j.hidden?<button className="text-button" onClick={()=>jobAction(j.id,'restore')}>恢复作品</button>:<button className="text-button danger-text" onClick={()=>askRemove([j.id])}>删除</button>}</div></article>}

 // Releases: edits show at once, are saved after a short pause, and stay on screen until the server has them.
 function saveRelease(id,body){return persist('/api/releases/'+id,body).then(()=>refresh()).then(()=>setReleaseEdits(prev=>{const mine={...(prev[id]||{})};for(const k in body)if(JSON.stringify(mine[k])===JSON.stringify(body[k]))delete mine[k];return {...prev,[id]:mine}})).catch(()=>{})}
